SELECT CASE WHEN s.risk_reward_ratio < 0.5 THEN 'a<0.5' WHEN s.risk_reward_ratio < 1 THEN 'b0.5-1' WHEN s.risk_reward_ratio < 1.5 THEN 'c1-1.5' ELSE 'd>=1.5' END AS rr_bucket, COUNT(*) AS n, SUM(p.realized_pnl > 0) AS wins, SUM(p.realized_pnl < 0) AS losses, SUM(p.status='STOPPED') AS stopped, ROUND(AVG((p.exit_price - p.entry_price)/p.entry_price*100),4) AS avg_gross_pct, ROUND(SUM(p.realized_pnl),6) AS sum_pnl FROM paper_position p JOIN trade_signal s ON s.id=p.signal_id WHERE p.opened_at >= '2026-10-11 00:00:00' AND p.status IN ('CLOSED','STOPPED') GROUP BY rr_bucket ORDER BY rr_bucket